/// Segment depth bound: seq values wrap at `2^SEQ_BITS`, and
/// claimable, committed, and released must stay distinct.
pub const MAX_SEG_CAPACITY: u32 = 1 << 24;

const _: () = assert!(SEG_SHIFT + MAX_SEGMENTS.trailing_zeros() <= 31);
