8	use zc_ring_x1::spsc::v3::segment_size;
9	use zc_ring_x1::{Empty, Pool, PoolHeader, Ring};
10	use zerocopy::{FromBytes, Immutable, IntoBytes, KnownLayout};
11	
12	/// The message. Any `#[repr(C)]` type the zerocopy traits accept,
13	/// at most the slot body in size: `SLOT` less the crate's
14	/// `SLOT_HEADER_BYTES`, 64 less 4 here.
15	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable)]
16	#[repr(C)]
17	struct Msg {
18	    seq: u64,
19	    payload: [u8; 16],
20	}
21	
22	/// Bytes per slot, a cache-line multiple. One line holds the
23	/// crate's 4-byte slot header and up to 60 bytes of message.
24	const SLOT: u32 = 64;
25	
26	/// Slots per segment, a power of two.
27	const DEPTH: u32 = 64;
28	
29	/// Segments in the ring, 1 to 32. With a consumer that keeps up
30	/// only the first is used, and the rest absorb a producer that
31	/// runs ahead.
32	const SEGMENTS: u32 = 4;
33	
34	/// Messages the run moves.
35	const COUNT: u64 = 1_000_000;
36	
37	/// One cache line of backing store, so a `Vec<Line>` is a
38	/// line-aligned region of any size the pool wants.
39	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Clone)]
40	#[repr(C, align(64))]
41	struct Line([u8; 64]);
42	
43	/// A wait policy: spin briefly, then yield the thread, and never
44	/// give up. The crate ships `policy::spin`, and any
45	/// `FnMut(u32) -> bool` works, the argument the failed attempts
46	/// so far and the return whether to try again.
47	fn spin_then_yield(attempt: u32) -> bool {
48	    if attempt < 100 {
49	        core::hint::spin_loop();
50	    } else {
51	        std::thread::yield_now();
52	    }
53	    true
54	}
55	
56	fn main() {
57	    // 1. A pool whose buffers hold one segment each, and enough of
58	    //    them for the ring. `segment_size` is the bytes a segment
59	    //    of DEPTH slots of SLOT bytes needs, header included.
60	    let seg_bytes = segment_size(SLOT, DEPTH);
61	    let region_bytes = size_of::<PoolHeader>() as u64 + seg_bytes * SEGMENTS as u64;
62	    let mut store = vec![Line([0; 64]); region_bytes.div_ceil(64) as usize];
63	    let mut pool = Pool::init(
64	        store.as_mut_slice().as_mut_bytes(),
65	        seg_bytes as u32,
66	        SEGMENTS,
67	    )
68	    .expect("the store is sized for the header and the segments"); // OK: sized above from segment_size
69	
70	    // 2. The ring takes its segments from the pool at init, and
71	    //    split hands out the two endpoints, each once. The pool is
72	    //    borrowed only during init.
73	    let (mut producer, mut consumer) = Ring::init(&mut pool, SLOT, DEPTH, SEGMENTS)
74	        .expect("the pool holds the segments") // OK: the pool was made for them
75	        .split();
76	
77	    // 3. The endpoints are Send, so each moves to its own thread.
78	    let (sent, seen) = std::thread::scope(|s| {
79	        let producer = s.spawn(move || {
80	            for i in 0..COUNT {
81	                // Reserve the next slot as a `&mut Msg`, fill it in
82	                // place, and commit. Dropping the guard instead of
83	                // committing abandons the reservation.
84	                let mut slot = producer
85	                    .reserve_slot_with::<Msg>(spin_then_yield)
86	                    .expect("the policy never gives up"); // OK: spin_then_yield returns true
87	                slot.seq = i;
88	                slot.payload = [i as u8; 16];
89	                slot.commit();
90	            }
91	            (producer.switches(), producer.segment())
92	        });
93	        let consumer = s.spawn(move || {
94	            let mut checksum = 0u64;
95	            for i in 0..COUNT {
96	                // Reserve the oldest unread slot as a `&Msg`, read it,
97	                // and release it. Dropping the guard instead of
98	                // releasing re-delivers the same slot next time.
99	                let msg = consumer
100	                    .reserve_slot_with::<Msg>(spin_then_yield)
101	                    .expect("the policy never gives up"); // OK: spin_then_yield returns true
102	                assert_eq!(msg.seq, i, "messages arrive in order");
103	                checksum = checksum.wrapping_add(msg.payload[0] as u64);
104	                msg.release();
105	            }
106	            // A single non-blocking probe: `|_| false` gives up at
107	            // once, and an empty ring reports Empty.
108	            assert_eq!(
109	                consumer.reserve_slot_with::<Msg>(|_| false).err(),
110	                Some(Empty)
111	            );
112	            (consumer.switches(), consumer.segment(), checksum)
113	        });
114	        (
115	            producer.join().expect("producer ran"), // OK: a panic is the run's failure
116	            consumer.join().expect("consumer ran"), // OK: a panic is the run's failure
117	        )
118	    });
119	
120	    // 4. The counters: switches are segment changes, zero when the
121	    //    consumer kept up, and both sides agree once everything sent
122	    //    has been read. `segment` is where each side ended.
123	    let (p_switches, p_segment) = sent;
124	    let (c_switches, c_segment, checksum) = seen;
125	    assert_eq!(p_switches, c_switches, "both sides count the same switches");
126	    assert_eq!(p_segment, c_segment, "both sides end in the same segment");
127	    println!(
128	        "spsc v3: {COUNT} messages, {SEGMENTS} segments of {DEPTH}, \
129	         {p_switches} switches, ended in segment {p_segment}, checksum {checksum}"
130	    );
131	}

